package local.velo.bridge;
import android.app.*;import android.bluetooth.*;import android.content.*;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.UUID;
/** One Bluetooth owner for both standby and active rides. */
public final class DeviceLinkService extends Service {
 static volatile String lastSent;static volatile long sentAt;static volatile String state="码表待连接";volatile boolean alive;volatile BluetoothSocket socket;Thread worker;volatile String address;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){String next=i==null?null:i.getStringExtra("address");if(next==null){stopSelf();return START_NOT_STICKY;}NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("device","码表连接",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"device").setSmallIcon(android.R.drawable.stat_sys_data_bluetooth).setContentTitle("VELO 码表连接").setContentText("自动连接已选码表，断线后重试").setContentIntent(open).setOngoing(true).build();if(Build.VERSION.SDK_INT>=29)startForeground(2,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);else startForeground(2,n);if(alive){if(!next.equals(address)){address=next;close();}return START_NOT_STICKY;}address=next;alive=true;worker=new Thread(()->loop(),"velo-device-link");worker.start();return START_NOT_STICKY;}
 void close(){try{if(socket!=null)socket.close();}catch(Exception ignored){}}
 void loop(){while(alive){try{state="正在连接码表";String target=address;BluetoothAdapter adapter=getSystemService(BluetoothManager.class).getAdapter();socket=adapter.getRemoteDevice(target).createRfcommSocketToServiceRecord(UUID.fromString("00001101-0000-1000-8000-00805F9B34FB"));socket.connect();RideService.connected=true;state="码表已连接";OutputStream out=socket.getOutputStream();out.write("LIVE\n".getBytes(StandardCharsets.US_ASCII));while(alive&&target.equals(address)){RideService.Frame f=RideService.running?RideService.outgoing:null;String text=f!=null&&SystemClock.elapsedRealtime()-f.time<5000?f.text:"D,-1,0,0,N,-1\nMAPOFF\n";out.write(text.getBytes(StandardCharsets.US_ASCII));out.flush();lastSent=text;sentAt=SystemClock.elapsedRealtime();Thread.sleep(1000);}}catch(Exception e){state="码表未连接 · 自动重试";}finally{RideService.connected=false;lastSent=null;sentAt=0;close();socket=null;}if(alive)try{Thread.sleep(3000);}catch(InterruptedException e){break;}}}
 public void onDestroy(){alive=false;lastSent=null;sentAt=0;close();if(worker!=null)worker.interrupt();RideService.connected=false;state="码表待连接";stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
